unit.function:
def create_private_key():
    '''
    Generate a private key using RSA,
    export the key using the OpenSSH format,
    then return it.
    '''
    key = RSA.generate(1024)
    return key.exportKey('OpenSSH')

def getSessionID():
    '''
    Return a random and unique session ID.
    '''
    return random.randint(0, 0xFFFFFFFF)

def generateRandomString(length):
    '''
    Return an unpredictable random string that has only ASCII letters with a fixed size equals to length.
    '''
    return ''.join(random.choice(string.ascii_letters) for i in range(length))

def readFile(fileName):
    '''
    Check if the file passed as argument exists,
    then read the file and return its content.
    '''

    if os.path.exists(fileName):
        with open(fileName, 'r') as f:
            return f.read()

def getData(dataStart, dataLimit, thread): ''' Check if the dataStart is less than or equal to dataLimit. If so, acquire a thread lock, increase the dataStart by 1 by, and then unlock the thread. Print which thread is currently accessing the data ''' lock = threading.Lock()
if dataStart <= dataLimit: lock.acquire() dataStart += 1 lock.release()
print("data from A :: " + str(dataStart) + " Accessor thread :: " + threading.get_ident()) time.sleep(0.5)

